script:
files = ["src/a.txt", "src/nested/b.txt"]
before = {f: repo.read(f) for f in files}
for f in files:
    repo.edit(f, "slow_path", "fast_path", all=True)
remaining = repo.search("slow_path", glob="src/**")
other = repo.search("slow_path", glob="**")
paths = {}
for h in other:
    paths[h.path] = True
commit()
return {
    "before": before,
    "after": {f: repo.read(f) for f in files},
    "remaining_in_src": len(remaining),
    "all_matches_paths": sorted(paths.keys()),
    "diff": repo.diff(),
}
